-- SM1: починка 36 старых уроков (Unit 0–5), 07.10.2026.
-- Собрано скриптом из проверки docs/SM1_проверка_старых_уроков.md.
-- Картинки base64 не переписываются: правки идут через jsonb_set / replace по тексту
-- без base64 / перестановку элементов массива на сервере.
--
-- ОТКАТ: исходные payload всех 513 блоков курса лежат в classroom_blocks_backup_sm1_20261007
-- (id, payload_text — полностью, с base64), уроков — в classroom_lessons_backup_sm1_20261007.
--   update classroom_blocks b set payload = k.payload_text::jsonb, updated_at = now()
--     from classroom_blocks_backup_sm1_20261007 k where k.id = b.id;          -- все блоки
--   (или с условием and b.id = '<id>' — один блок)
--   update classroom_lessons set sort_order = 100 + sort_order where unit_id = '<unit0>';  -- затем
--   update classroom_lessons l set sort_order = k.sort_order, title = k.title
--     from classroom_lessons_backup_sm1_20261007 k where k.id = l.id;

-- 0. Бэкап (сделан до первой правки)
create table if not exists classroom_blocks_backup_sm1_20261007 as
select b.id, b.lesson_id, b.type, b.sort_order, b.payload::text as payload_text, b.updated_at, now() as saved_at
  from classroom_blocks b join classroom_lessons l on l.id = b.lesson_id
  join classroom_units u on u.id = l.unit_id join classroom_courses c on c.id = u.course_id
 where c.slug = 'sm1';
create table if not exists classroom_lessons_backup_sm1_20261007 as
select l.id, l.title, l.sort_order, l.updated_at, now() as saved_at
  from classroom_lessons l join classroom_units u on u.id = l.unit_id join classroom_courses c on c.id = u.course_id
 where c.slug = 'sm1';
alter table classroom_blocks_backup_sm1_20261007 enable row level security;
alter table classroom_lessons_backup_sm1_20261007 enable row level security;

